      "WorkflowArtifacts.ProducingAgentType": {
        "table": "WorkflowArtifacts",
        "field": "ProducingAgentType",
        "kind": "formula",
        "rule": "Il campo “producing agent type” del workflow artifact è determinato secondo la seguente priorità:\n1. «HumanAgent», se l'attributed to human agent ha un valore;\n2. «AIAgent», se l'attributed to AI agent ha un valore;\n3. «AutomatedPipeline», se l'attributed to automated pipeline ha un valore;\n4. in tutti gli altri casi, una stringa vuota.",
        "mechanical": false,
        "refs": [
          {
            "table": "WorkflowArtifacts",
            "field": "AttributedToHumanAgent",
            "label": "attributed to human agent"
          },
          {
            "table": "WorkflowArtifacts",
            "field": "AttributedToAIAgent",
            "label": "attributed to AI agent"
          },
          {
            "table": "WorkflowArtifacts",
            "field": "AttributedToAutomatedPipeline",
            "label": "attributed to automated pipeline"
          }
        ],
        "structure": {
          "kind": "priority",
          "headline": "Il campo “producing agent type” del workflow artifact è determinato secondo la seguente priorità:",
          "cases": [
            {
              "value": "«HumanAgent»",
              "when": {
                "kind": "leaf",
                "text": "l'attributed to human agent ha un valore"
              }
            },
            {
              "value": "«AIAgent»",
              "when": {
                "kind": "leaf",
                "text": "l'attributed to AI agent ha un valore"
              }
            },
            {
              "value": "«AutomatedPipeline»",
              "when": {
                "kind": "leaf",
                "text": "l'attributed to automated pipeline ha un valore"
              }
            },
            {
              "value": "una stringa vuota",
              "when": null
            }
          ],
          "children": null
        },
        "plain": "Se non attributed to human agent è vuoto, allora \"HumanAgent\", altrimenti se non attributed to AI agent è vuoto, allora \"AIAgent\", altrimenti se non attributed to automated pipeline è vuoto, allora \"AutomatedPipeline\", altrimenti \"\""
      },
